{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "In rats, bupropion—the closest analogue sharing the 3-chlorophenyl and chiral methylamine motif—showed rapid brain equilibration with a Kp,uu of 1.9 by quantitative microdialysis, demonstrating that this scaffold achieves meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Hydroxybupropion, another close analogue, also equilibrated rapidly across the rat BBB with a Kp,uu of 1.7, independently supporting CNS access for this 3-chlorophenyl-containing scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "The neutral amide-containing PET tracer FNDP showed high and rapid brain uptake in baboons, supporting that amide-bearing lipophilic molecules of this type can cross the BBB.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Pass. The query is a neutral, moderately lipophilic amide with physicochemical properties consistent with passive BBB penetration, and the closest experimental analogues (bupropion/hydroxybupropion) show Kp,uu >1 in rat; amide-containing lipophilic tracers also show high brain uptake. No strong contradictory evidence transfers.",
  "evidence_gaps": [
    "No direct Kp,uu, CSF, or brain uptake data exist for the exact query molecule.",
    "Bupropion's high Kp,uu is partly transporter-mediated, and the query lacks the basic amine responsible for that active uptake.",
    "Morgan similarities to the most relevant evidence molecules are modest (0.30-0.44), so transferability is not exact."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

